import React, { useEffect, useRef } from 'react';

interface BoldReportProps {
  apiUrl: string;
  reportName: string;
  tenantId?: string;
}

declare const $: any;

export const BoldReport: React.FC<BoldReportProps> = ({ apiUrl, reportName, tenantId }) => {
  const viewerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const loadViewer = () => {
      if (viewerRef.current && typeof $(viewerRef.current).BoldReportViewer === 'function') {
        $(viewerRef.current).BoldReportViewer({
          id: 'reportViewer',
          reportServiceUrl: apiUrl,
          reportPath: reportName,
          parameters: [
            { name: 'TenantId', value: tenantId || '00000000-0000-0000-0000-000000000000' },
            { name: 'ReportGeneratedOn', value: new Date().toISOString() },
          ],
          toolbarSettings: { showToolbar: true },
          height: '100%',
        });
      } else {
        setTimeout(loadViewer, 100); // Retry until BoldReportViewer is available
      }
    };

    loadViewer();
  }, [apiUrl, reportName, tenantId]);

  return <div ref={viewerRef} style={{ height: '900px', width: '100%' }} />;
};
